// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(uint256 amount, address probe) public {
        vm.assume(probe != address(0));
        // owner of c is the deployer (this test contract); NETM mints totalDistributed to owner
        c.NETM();
        amount = bound(amount, 1, c.totalDistributed());
        // owner moves a fuzzed amount out; correct contract has the NETM-minted balance
        bool ok;
        try c.transfer(probe, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.balanceOf(address(this)) == c.totalDistributed() - amount && c.balanceOf(probe) == amount);
    }
}
